-- 6. Seed Scenario Events
IF NOT EXISTS (SELECT 1 FROM [scenario].[ScenarioEvents] WHERE [ScenarioVersionId] = @ScenarioVersionId_SCM_001_V1 AND [Title] = N'Sự cố máy phát điện kho lạnh DC Cần Thơ gặp trục trặc (Event E1)')
BEGIN
    INSERT INTO [scenario].[ScenarioEvents] ([ScenarioVersionId], [Title], [Description], [TriggerType], [TriggerConditionJson], [EventContent], [DisplayOrder], [IsActive])
    VALUES (@ScenarioVersionId_SCM_001_V1, N'Sự cố máy phát điện kho lạnh DC Cần Thơ gặp trục trặc (Event E1)', N'Trạm biến áp khu công nghiệp bị sét đánh gây mất điện lưới, máy phát điện dự phòng tại DC Cần Thơ chỉ hoạt động 50% công suất làm nhiệt độ kho tăng dần.', N'Manual', NULL, N'Vào lúc 02:00 sáng mùa mưa bão, trạm biến áp cấp điện cho Khu công nghiệp Trà Nóc bị sự cố nổ đường dây dẫn tới mất điện toàn khu vực. Hệ thống tự động chuyển nguồn sang máy phát điện diesel dự phòng tại DC Cần Thơ nhưng máy phát số 2 bị kẹt van dầu, chỉ duy trì được 50% công suất tải.

Hệ thống WMS ghi nhận nhiệt độ hầm lạnh chứa 12.000 pallet thủy sản xuất khẩu tăng dần từ -23°C lên -13.5°C trong vòng 4 tiếng rưỡi (vượt ngưỡng an toàn -15°C).

Còi báo động gửi tin nhắn khẩn cấp cho Giám đốc DC và Trưởng phòng QA. Ban giám đốc phải quyết định kích hoạt quy trình điều chuyển hàng khẩn cấp (Emergency Cargo Evacuation) sang DC Củ Chi hoặc thuê gấp các xe lạnh di động để cắm nguồn bảo quản tạm.', 1, 1);
END;
IF NOT EXISTS (SELECT 1 FROM [scenario].[ScenarioEvents] WHERE [ScenarioVersionId] = @ScenarioVersionId_SCM_001_V1 AND [Title] = N'Sự cố nghẽn cửa Dock cao điểm xuất khẩu thủy sản dịp cuối năm (Event E2)')
BEGIN
    INSERT INTO [scenario].[ScenarioEvents] ([ScenarioVersionId], [Title], [Description], [TriggerType], [TriggerConditionJson], [EventContent], [DisplayOrder], [IsActive])
    VALUES (@ScenarioVersionId_SCM_001_V1, N'Sự cố nghẽn cửa Dock cao điểm xuất khẩu thủy sản dịp cuối năm (Event E2)', N'Hơn 75 xe container và xe tải đông lạnh đồng loạt cập bến DC Củ Chi trong khi kho chỉ có 12 cửa Dock tiếp nhận, gây ùn tắc giao thông và nguy cơ thiếu dầu máy lạnh.', N'Manual', NULL, N'Vào tuần lễ cao điểm xuất khẩu hàng hóa trước kỳ nghỉ lễ, hơn 75 xe tải và container đông lạnh từ các tỉnh miền Tây đồng loạt dồn về Tổng kho DC Củ Chi trong buổi sáng sớm, vượt gấp 3 lần năng lực tiếp nhận tối đa của 12 cửa Dock.

Xe tải phải xếp hàng nối đuôi dài hơn 2km ngoài tỉnh lộ. Hàng chục tài xế tắt máy xe và đe dọa tắt luôn máy lạnh thùng xe vì xe sắp cạn dầu sau 5 tiếng chờ đợi dưới trời nắng gắt.

Đội vận hành kho và QA tranh cãi nảy lửa: Vận hành muốn bỏ qua quy trình đo nhiệt độ từng pallet để cho hàng nhập tràn vào sàn đệm, trong khi QA kiên quyết giữ nguyên quy trình kiểm tra gắt gao từng kiện hàng trước khi mở cửa kho.', 2, 1);
END;

